/*
 * Unix crypt(3) fallback loader.
 * The actual implementation is unix-crypt-td-js 1.1.4.
 * This local file is intentionally tiny so Worker environments can fall back
 * to the package when a deployment accidentally omits the bundled library.
 */
(function(){
  if (typeof self !== "undefined" && typeof self.unixCryptTD !== "function") {
    try {
      importScripts("https://cdn.jsdelivr.net/npm/unix-crypt-td-js@1.1.4/unix-crypt-td.min.js");
    } catch (e) {}
  }
})();
